  "inlineSchema": "// Nova AI Studio - Prisma Schema\n// 数据库: PostgreSQL (Supabase / Neon 免费层)\n// 生成客户端: npx prisma generate\n// 推送表结构: npx prisma db push\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  USER\n  ADMIN\n}\n\nenum Plan {\n  FREE\n  PRO\n  ENTERPRISE\n}\n\nmodel User {\n  id                   String    @id @default(cuid())\n  name                 String?\n  email                String    @unique\n  emailVerified        DateTime?\n  image                String?\n  passwordHash         String?\n  role                 Role      @default(USER)\n  plan                 Plan      @default(FREE)\n  stripeCustomerId     String?   @unique\n  stripeSubscriptionId String?   @unique\n  subscriptionStatus   String? // active / trialing / past_due / canceled\n  createdAt            DateTime  @default(now())\n  updatedAt            DateTime  @updatedAt\n\n  accounts    Account[]\n  sessions    Session[]\n  generations Generation[]\n  orders      Order[]\n}\n\n// ---- NextAuth 标准模型 ----\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// ---- 业务模型 ----\n\n// 每次 AI 生成记录（用于配额统计与管理员审计）\nmodel Generation {\n  id        String   @id @default(cuid())\n  userId    String\n  type      String // short | novel | code | chat\n  prompt    String   @db.Text\n  output    String   @db.Text\n  engine    String? // 实际使用的模型/引擎\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n}\n\n// 订单（Stripe Checkout 会话）\nmodel Order {\n  id              String    @id @default(cuid())\n  userId          String\n  stripeSessionId String?   @unique\n  plan            Plan\n  amount          Int // 美分，如 990 = $9.90\n  currency        String    @default(\"usd\")\n  status          String    @default(\"pending\") // pending | paid | canceled | refunded\n  createdAt       DateTime  @default(now())\n  paidAt          DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n}\n\n// 站点设置（管理员可改）\nmodel SiteSettings {\n  key       String   @id\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n}\n",
